local HEX = [[]]

local function fromHex(h)
	local n = #h // 2
	local b = buffer.create(n)
	for i = 0, n - 1 do
		buffer.writeu8(b, i, tonumber(string.sub(h, i * 2 + 1, i * 2 + 2), 16))
	end
	return b
end

local entry = loadstring(CHUNK, "=prism")
if type(entry) ~= "function" then
	error("prism: chunk does not compile")
end

-- the chunk runs its 36-state initialisation and returns the program entry point
local main = entry(fromHex(HEX))
if type(main) == "function" then
	return main()
end
return main
